mapper.select:
SELECT ORDER_STATUS
FROM F2F_ORDER
WHERE ORDER_NO = #{orderNo,jdbcType=VARCHAR}

SELECT 
FROM F2F_ORDER
WHERE ACTIVATE_DEVICE_ID = #{deviceId,jdbcType=VARCHAR}
  AND QRCODE_GEN_DATE = #{qrcodeGenDate,jdbcType=VARCHAR}
  AND RANDOM_FACT = #{randomFact,jdbcType=VARCHAR}

SELECT 
FROM F2F_ORDER
WHERE CHANNEL = #{channel,jdbcType=VARCHAR}
  AND DEVICE_ID = #{deviceId,jdbcType=VARCHAR}
  AND DEVICE_SEQ = #{deviceSeq,jdbcType=VARCHAR}

SELECT 
FROM F2F_ORDER
WHERE THIRD_USER_ID = #{thirdUserId,jdbcType=VARCHAR}
  AND ACTIVATE_FLAG = #{activateFlag,jdbcType=VARCHAR}
ORDER BY CREATE_TMS DESC

SELECT 
FROM F2F_ORDER
WHERE CARD_ID = #{cardId,jdbcType=VARCHAR}

  AND BIZ_TYPE = #{bizType,jdbcType=VARCHAR}

ORDER BY CREATE_TMS DESC
FETCH FIRST 1 ROWS ONLY

where.if:
AND EXISTS (
    SELECT 1 FROM F2F_PAYMENT P
    WHERE P.ORDER_NO = F2F_ORDER.ORDER_NO
      AND P.PAY_CENTER_ORDER_NO = #{payCenterOrderNo,jdbcType=VARCHAR}
)

AND EXISTS (
    SELECT 1 FROM F2F_PAYMENT P
    WHERE P.ORDER_NO = F2F_ORDER.ORDER_NO
      AND P.CHANNEL_ORDER_NO = #{payCenterChannelOrderNo,jdbcType=VARCHAR}
)
